namespace AetherArk.Content
{
    /// <summary>Event strings. Generated from tools/gen_events.py data; keep in sync with EncounterLibrary.</summary>
    public sealed partial class LocalizationService
    {
        private void AddEncounterStrings()
        {
            Add("enc.burning_ferry.title", "불타는 연락선", "THE BURNING FERRY");
            Add("enc.burning_ferry.body", "엔진 화재가 번진 연락선이 구름 위를 헤맵니다. 갑판에 승객이 몰려 있고, 불길은 몇 분 안에 연료고에 닿을 것입니다.", "A ferry drifts above the clouds with an engine fire spreading toward its fuel bunker. Passengers crowd the deck; you have minutes.");
            Add("enc.burning_ferry.teams", "소화반을 보내 차분히 구조한다 (보급 1)", "Send fire teams and evacuate methodically (1 supply)");
            Add("enc.burning_ferry.teams.r", "소화반이 불길을 잡는 동안 승객 40명이 옮겨 탔습니다.", "Fire teams hold the blaze while forty passengers cross.");
            Add("enc.burning_ferry.dash", "선체를 붙이고 전원 탈출시킨다 — 위험한 접근", "Lash hulls and take everyone — a dangerous approach");
            Add("enc.burning_ferry.dash.r", "무모했지만 통했습니다. 70명이 살았고 선단이 환호합니다.", "Reckless, but it works. Seventy are saved and the convoy cheers.");
            Add("enc.burning_ferry.dash_fail", "연료고 폭발", "The bunker detonates");
            Add("enc.burning_ferry.dash_fail.r", "연료고가 터지며 선체가 그을렸습니다. 20명만 구했습니다.", "The bunker blows; the hull is scorched and only twenty are pulled clear.");
            Add("enc.burning_ferry.leave", "거리를 둔다", "Keep your distance");
            Add("enc.burning_ferry.leave.r", "폭발의 빛이 구름을 물들이고, 선단은 침묵합니다.", "The explosion lights the clouds, and the convoy falls silent.");
            Add("enc.ice_locked_lifeboats.title", "결빙된 구명정", "ICE-LOCKED LIFEBOATS");
            Add("enc.ice_locked_lifeboats.body", "얼어붙은 구명정 세 척이 빙운 속에 갇혀 있습니다. 안에서 두드리는 소리가 들립니다.", "Three lifeboats hang frozen inside an ice cloud. Something knocks from within.");
            Add("enc.ice_locked_lifeboats.thaw", "[드워프] 용광로 배관으로 천천히 녹인다 (보급 1)", "[Dwarf] Thaw them with forge lines (1 supply)");
            Add("enc.ice_locked_lifeboats.thaw.r", "드워프 기술자들이 얼음을 녹여 30명을 무사히 데려왔습니다.", "Dwarven hands melt the ice away and thirty come aboard unharmed.");
            Add("enc.ice_locked_lifeboats.blast", "에테르로 얼음을 깨뜨린다 (에테르 1)", "Crack the ice with an aether pulse (1 aether)");
            Add("enc.ice_locked_lifeboats.blast.r", "얼음이 깨지고 구명정과 장비를 회수했습니다.", "The ice shatters; you recover the boats and their gear.");
            Add("enc.ice_locked_lifeboats.leave", "두드림을 뒤로하고 떠난다", "Leave the knocking behind");
            Add("enc.ice_locked_lifeboats.leave.r", "두드리는 소리가 잦아들 때까지 아무도 말을 하지 않았습니다.", "No one speaks until the knocking fades.");
            Add("enc.mutiny_transport.title", "반란 수송선", "THE MUTINOUS TRANSPORT");
            Add("enc.mutiny_transport.body", "수송선의 승무원이 선장을 가두고 선단 합류를 요구합니다. 승객들은 겁에 질려 있습니다.", "A transport's crew has locked up their captain and demand to join the convoy. The passengers are terrified.");
            Add("enc.mutiny_transport.intimidate", "[오크] 무장 승무원을 보내 질서를 잡는다", "[Orc] Send armed crew to restore order");
            Add("enc.mutiny_transport.intimidate.r", "반란자들은 오크 해병을 보자마자 무기를 내렸습니다.", "The mutineers drop their weapons the moment the orc marines board.");
            Add("enc.mutiny_transport.negotiate", "보급 2를 주고 협상한다", "Negotiate with 2 supplies");
            Add("enc.mutiny_transport.negotiate.r", "보급을 나누자 양측이 합류에 동의했습니다.", "Shared stores bring both sides to the table.");
            Add("enc.mutiny_transport.refuse", "반란선을 선단에 들이지 않는다", "Refuse the mutineers");
            Add("enc.mutiny_transport.refuse.r", "수송선은 홀로 구름 속으로 사라졌습니다.", "The transport vanishes alone into the clouds.");
            Add("enc.plague_barge.title", "역병 바지선", "THE PLAGUE BARGE");
            Add("enc.plague_barge.body", "격리 깃발을 단 바지선이 도움을 청합니다. 생존자들은 열에 시달리지만 아직 걸을 수 있습니다.", "A barge flying quarantine flags pleads for help. Its survivors are feverish but still on their feet.");
            Add("enc.plague_barge.quarantine", "[병원선] 격리 병동으로 받아들인다", "[Hospital ship] Take them into the isolation ward");
            Add("enc.plague_barge.quarantine.r", "병원선이 환자를 받았고 역병은 번지지 않았습니다.", "The hospital ship takes the sick, and the fever spreads no further.");
            Add("enc.plague_barge.take", "그냥 받아들인다 — 절반의 도박", "Take them anyway — a coin toss");
            Add("enc.plague_barge.take.r", "열이 가라앉았습니다. 60명이 합류했습니다.", "The fever breaks. Sixty join the convoy.");
            Add("enc.plague_barge.take_fail", "역병 확산", "The fever spreads");
            Add("enc.plague_barge.take_fail.r", "역병이 선단에 번져 30명을 잃었습니다.", "The fever spreads through the convoy and thirty are lost.");
            Add("enc.plague_barge.refuse", "떠난다", "Leave them");
            Add("enc.plague_barge.refuse.r", "바지선의 신호가 점점 약해집니다.", "The barge's signal grows fainter.");
            Add("enc.child_choir.title", "떠도는 성가대", "THE WANDERING CHOIR");
            Add("enc.child_choir.body", "음악학교 비행선이 연료를 다 쓰고 표류합니다. 아이들이 갑판에서 노래하며 신호를 보냅니다.", "A music-school airship has run dry. Children on its deck sing to signal you.");
            Add("enc.child_choir.take", "모두 태운다 (보급 1)", "Take them all aboard (1 supply)");
            Add("enc.child_choir.take.r", "성가대의 노래가 선단 통신망에 퍼지자 사기가 치솟았습니다.", "Their song spreads across the convoy channel and morale soars.");
            Add("enc.child_choir.fuel", "에테르 1을 나눠 준다", "Share 1 aether");
            Add("enc.child_choir.fuel.r", "비행선은 다시 떠올랐고, 아이들이 손을 흔들었습니다.", "The airship lifts again; the children wave.");
            Add("enc.child_choir.leave", "지나친다", "Pass them by");
            Add("enc.child_choir.leave.r", "노래가 뒤에서 잦아듭니다.", "The song fades behind you.");
            Add("enc.imperial_deserters.title", "제국 탈영병", "IMPERIAL DESERTERS");
            Add("enc.imperial_deserters.body", "제국 순찰정 한 척이 항복 깃발을 올렸습니다. 승무원은 탈영을 원하며 무기고를 대가로 내놓습니다.", "An imperial picket raises a surrender flag. Its crew want to desert and offer their magazine in return.");
            Add("enc.imperial_deserters.accept", "받아들인다", "Take them in");
            Add("enc.imperial_deserters.accept.r", "군수품을 받았지만 선단 일부는 제국 제복을 불신합니다.", "You gain ordnance, but parts of the convoy distrust the uniforms.");
            Add("enc.imperial_deserters.interrogate", "[인간] 옛 동료로서 항로 정보를 얻는다", "[Human] Trade on old ties for route intelligence");
            Add("enc.imperial_deserters.interrogate.r", "탈영병이 제국 연료고 좌표를 넘겼습니다.", "The deserters hand over the coordinates of an imperial fuel cache.");
            Add("enc.imperial_deserters.refuse", "거절한다", "Turn them away");
            Add("enc.imperial_deserters.refuse.r", "순찰정은 항복 깃발을 내리고 멀어졌습니다.", "The picket lowers its flag and drifts away.");
            Add("enc.stranded_engineers.title", "조난 기술자", "STRANDED ENGINEERS");
            Add("enc.stranded_engineers.body", "부서진 정비선의 기술자들이 공구를 든 채 구조를 기다립니다.", "Engineers from a wrecked tender wait for rescue, tools in hand.");
            Add("enc.stranded_engineers.take", "태우고 수리를 맡긴다", "Take them aboard and put them to work");
            Add("enc.stranded_engineers.take.r", "기술자들이 선체 균열을 메웠습니다.", "The engineers weld the flagship's cracks shut.");
            Add("enc.stranded_engineers.pay", "인양물 3을 주고 정식 수리를 부탁한다", "Pay 3 salvage for a proper refit");
            Add("enc.stranded_engineers.pay.r", "자재를 받은 기술자들이 장갑판까지 손봤습니다.", "With materials in hand they patch armor as well as hull.");
            Add("enc.stranded_engineers.leave", "떠난다", "Leave them");
            Add("enc.stranded_engineers.leave.r", "정비선의 불빛이 꺼졌습니다.", "The tender's lights go dark.");
            Add("enc.sky_whale_calf.title", "다친 하늘고래 새끼", "THE WOUNDED SKY-WHALE CALF");
            Add("enc.sky_whale_calf.body", "그물에 얽힌 하늘고래 새끼가 선단 곁을 맴돕니다. 어미는 보이지 않습니다.", "A sky-whale calf tangled in netting circles the convoy. Its mother is nowhere in sight.");
            Add("enc.sky_whale_calf.calm", "[조인] 노래로 달래며 그물을 푼다", "[Avian] Sing it calm and cut the net");
            Add("enc.sky_whale_calf.calm.r", "풀려난 새끼가 에테르 결정을 떨어뜨리고 떠났습니다.", "Freed, the calf sheds an aether crystal and swims away.");
            Add("enc.sky_whale_calf.free", "보급 1을 미끼로 그물을 푼다", "Lure it with 1 supply and cut the net");
            Add("enc.sky_whale_calf.free.r", "새끼가 선단 주위를 한 바퀴 돌고 사라졌습니다.", "The calf circles the convoy once and vanishes.");
            Add("enc.sky_whale_calf.harvest", "사냥해 자원으로 쓴다", "Harvest it");
            Add("enc.sky_whale_calf.harvest.r", "자원은 얻었지만 선단은 그 울음을 잊지 못합니다.", "The convoy gains salvage and cannot forget the sound it made.");
            Add("enc.wreck_signal_trap.title", "부르는 난파선", "THE WRECK THAT CALLED");
            Add("enc.wreck_signal_trap.body", "구조 신호가 나오는 난파선 주위로 기류가 이상하게 고요합니다.", "A wreck broadcasts a distress call. The air around it is strangely still.");
            Add("enc.wreck_signal_trap.detect", "[정찰선] 주변을 먼저 훑는다", "[Pathfinder] Sweep the approach first");
            Add("enc.wreck_signal_trap.detect.r", "정찰선이 매복 기뢰를 찾아냈고, 난파선은 조용히 인양됐습니다.", "The pathfinder finds the ambush mines; the wreck is quietly salvaged.");
            Add("enc.wreck_signal_trap.approach", "그대로 접근한다", "Approach directly");
            Add("enc.wreck_signal_trap.approach.r", "진짜 생존자였습니다. 50명이 합류했습니다.", "The call was real. Fifty survivors join you.");
            Add("enc.wreck_signal_trap.ambush", "매복", "Ambush");
            Add("enc.wreck_signal_trap.ambush.r", "난파선 뒤에서 제국 커터가 튀어나옵니다!", "An imperial cutter bursts from behind the wreck!");
            Add("enc.wreck_signal_trap.ignore", "무시한다", "Ignore the call");
            Add("enc.wreck_signal_trap.ignore.r", "신호가 뒤에서 되풀이됩니다.", "The signal repeats behind you.");
            Add("enc.derelict_cruiser.title", "표류 순양함", "THE DERELICT CRUISER");
            Add("enc.derelict_cruiser.body", "제국 순양함 한 척이 등을 꺼트린 채 표류합니다. 무장은 남아 있고 코어는 불안정하게 웅웅거립니다.", "An imperial cruiser drifts dark. Its guns are intact and its core hums unsteadily.");
            Add("enc.derelict_cruiser.strip", "무장고를 뜯어낸다", "Strip the magazines");
            Add("enc.derelict_cruiser.strip.r", "군수품과 부품을 확보했습니다.", "Ordnance and parts secured.");
            Add("enc.derelict_cruiser.core", "[드워프] 코어를 추출한다", "[Dwarf] Extract the core");
            Add("enc.derelict_cruiser.core.r", "코어가 안전하게 빠져나왔습니다.", "The core comes free cleanly.");
            Add("enc.derelict_cruiser.core_fail", "코어 폭주", "Core surge");
            Add("enc.derelict_cruiser.core_fail.r", "코어가 폭주하며 선체를 태웠습니다.", "The core surges and scorches the hull.");
            Add("enc.derelict_cruiser.leave", "손대지 않는다", "Leave it");
            Add("enc.derelict_cruiser.leave.r", "순양함은 계속 표류합니다.", "The cruiser drifts on.");
            Add("enc.aether_geyser.title", "에테르 간헐천", "THE AETHER GEYSER");
            Add("enc.aether_geyser.body", "구름 아래에서 에테르 기둥이 주기적으로 솟구칩니다.", "Columns of aether erupt from beneath the clouds at intervals.");
            Add("enc.aether_geyser.harvest", "코어를 열어 최대한 흡수한다", "Open the core and drink deep");
            Add("enc.aether_geyser.harvest.r", "에테르는 넘치지만 코어가 불안하게 떨립니다.", "Aether overflows; the core shudders.");
            Add("enc.aether_geyser.careful", "가장자리에서 조심스럽게 채집한다", "Skim the edges carefully");
            Add("enc.aether_geyser.careful.r", "안전하게 에테르를 채웠습니다.", "Aether gathered safely.");
            Add("enc.aether_geyser.pass", "지나간다", "Pass it by");
            Add("enc.aether_geyser.pass.r", "간헐천이 뒤에서 솟구칩니다.", "The geyser erupts behind you.");
            Add("enc.floating_monastery.title", "부유 수도원", "THE FLOATING MONASTERY");
            Add("enc.floating_monastery.body", "버려진 수도원이 조용히 떠 있습니다. 성유물과 낡은 기도문이 남아 있습니다.", "An abandoned monastery floats in silence, relics and worn prayers still inside.");
            Add("enc.floating_monastery.relics", "성유물을 가져간다", "Take the relics");
            Add("enc.floating_monastery.relics.r", "성유물은 값지지만 순례자들이 눈을 돌립니다.", "The relics are valuable; the pilgrims look away.");
            Add("enc.floating_monastery.prayers", "기도문을 선단에 낭독한다", "Read the prayers to the convoy");
            Add("enc.floating_monastery.prayers.r", "오래된 기도가 선단을 달랬습니다.", "Old words steady the convoy.");
            Add("enc.floating_monastery.resonate", "[엘프] 성가의 공명으로 코어를 채운다", "[Elf] Tune the core to the chant");
            Add("enc.floating_monastery.resonate.r", "성가가 코어에 에테르를 불어넣었습니다.", "The chant breathes aether into the core.");
            Add("enc.mine_field.title", "옛 기뢰 지대", "THE OLD MINEFIELD");
            Add("enc.mine_field.body", "옛 전쟁의 기뢰가 항로를 막습니다. 기뢰 사이에 침몰선 잔해가 보입니다.", "Mines from an old war block the lane. Wreckage glints between them.");
            Add("enc.mine_field.chart", "[정찰선] 안전한 길을 그린다", "[Pathfinder] Chart a safe path");
            Add("enc.mine_field.chart.r", "정찰선이 기뢰를 해체해 군수품으로 만들었습니다.", "The pathfinder defuses mines into ordnance.");
            Add("enc.mine_field.thread", "기뢰 사이를 통과한다", "Thread the mines");
            Add("enc.mine_field.thread.r", "잔해를 챙겨 무사히 빠져나왔습니다.", "You pull salvage from the wreck and slip out.");
            Add("enc.mine_field.thread_fail", "기뢰 접촉", "Mine strike");
            Add("enc.mine_field.thread_fail.r", "기뢰가 터져 장갑이 찢겼습니다.", "A mine detonates against the armor.");
            Add("enc.mine_field.avoid", "우회한다 (에테르 1)", "Go around (1 aether)");
            Add("enc.mine_field.avoid.r", "연료를 태워 기뢰 지대를 돌아갔습니다.", "You burn fuel to skirt the field.");
            Add("enc.crashed_courier.title", "추락한 급사선", "THE CRASHED COURIER");
            Add("enc.crashed_courier.body", "암호 장치가 켜진 채 추락한 제국 급사선이 있습니다.", "An imperial courier has crashed with its cipher engine still running.");
            Add("enc.crashed_courier.decode", "암호를 풀어 보급 좌표를 찾는다", "Decode it for depot coordinates");
            Add("enc.crashed_courier.decode.r", "근처 보급 좌표를 얻었습니다.", "You find a nearby depot's coordinates.");
            Add("enc.crashed_courier.sell", "장치를 뜯어 팔 준비를 한다", "Rip out the engine to sell");
            Add("enc.crashed_courier.sell.r", "암호 장치는 값이 나갈 것입니다.", "The engine will fetch a good price.");
            Add("enc.crashed_courier.burn", "급사선을 불태워 흔적을 지운다", "Burn the courier to hide your trail");
            Add("enc.crashed_courier.burn.r", "추격군이 며칠은 헤맬 것입니다.", "The pursuit will chase ghosts for days.");
            Add("enc.cloud_farm.title", "구름 농장 잔해", "THE CLOUD FARM");
            Add("enc.cloud_farm.body", "부서진 수경 농장이 떠다닙니다. 작물은 아직 살아 있고, 농부들도 일부 남았습니다.", "A broken hydroponic farm drifts by. Its crops still live, and so do a few farmers.");
            Add("enc.cloud_farm.harvest", "작물을 거둔다", "Harvest the crops");
            Add("enc.cloud_farm.harvest.r", "보급이 늘었습니다.", "Supplies replenished.");
            Add("enc.cloud_farm.settle", "농부들과 작물을 함께 태운다", "Take the farmers and their crops");
            Add("enc.cloud_farm.settle.r", "농부들이 선단 식량 관리를 맡았습니다.", "The farmers take charge of the convoy's rations.");
            Add("enc.cloud_farm.leave", "지나친다", "Leave it");
            Add("enc.cloud_farm.leave.r", "농장이 뒤로 멀어집니다.", "The farm drifts behind.");
            Add("enc.ordnance_cache.title", "봉인된 저장고", "THE SEALED CACHE");
            Add("enc.ordnance_cache.body", "제국 군수 저장고가 봉인된 채 절벽에 박혀 있습니다.", "A sealed imperial ordnance cache is wedged into a cliff.");
            Add("enc.ordnance_cache.careful", "천천히 봉인을 푼다", "Work the seal open slowly");
            Add("enc.ordnance_cache.careful.r", "군수품 일부를 회수했습니다.", "Some ordnance recovered.");
            Add("enc.ordnance_cache.blast", "폭파해서 연다", "Blow it open");
            Add("enc.ordnance_cache.blast.r", "저장고가 통째로 열렸습니다.", "The whole cache is yours.");
            Add("enc.ordnance_cache.blast_fail", "유폭", "Sympathetic detonation");
            Add("enc.ordnance_cache.blast_fail.r", "저장고가 유폭해 선체가 흔들렸습니다.", "The cache cooks off and rattles the hull.");
            Add("enc.ordnance_cache.leave", "건드리지 않는다", "Leave it sealed");
