            Add("enc.spy_aboard.ignore.r", "경고는 헛소리였습니다.", "The warning was nothing.");
            Add("enc.spy_aboard.sabotage", "파괴 공작", "Sabotage");
            Add("enc.spy_aboard.sabotage.r", "첩자가 연료를 빼돌리고 코어를 흔들었습니다.", "The spy bleeds fuel and rattles the core.");
            Add("enc.pilgrim_blockade.title", "문 앞의 순례자", "THE PILGRIMS AT THE GATE");
            Add("enc.pilgrim_blockade.body", "검문소가 순례자들을 막고 있습니다. 그들은 선단의 호위를 청합니다.", "A checkpoint is holding pilgrims back. They ask to travel under your protection.");
            Add("enc.pilgrim_blockade.escort", "에테르 1을 쓰며 호위한다", "Escort them (1 aether)");
            Add("enc.pilgrim_blockade.escort.r", "순례자들이 선단에 합류했습니다.", "The pilgrims join the convoy.");
            Add("enc.pilgrim_blockade.leave", "지나친다", "Pass on");
            Add("enc.pilgrim_blockade.leave.r", "순례자들이 뒤에 남았습니다.", "The pilgrims stay behind.");
            Add("enc.ion_squall.title", "이온 스콜", "THE ION SQUALL");
            Add("enc.ion_squall.body", "이온 스콜이 전 계기를 흔듭니다. 코어가 비명을 지릅니다.", "An ion squall rattles every instrument. The core screams.");
            Add("enc.ion_squall.calm", "에테르 1을 태워 코어를 진정시킨다", "Burn 1 aether to calm the core");
            Add("enc.ion_squall.calm.r", "코어가 진정됐습니다.", "The core settles.");
            Add("enc.ion_squall.push", "그대로 밀어붙인다", "Push through");
            Add("enc.ion_squall.push.r", "스콜을 뚫었고 잔류 에테르를 회수했습니다.", "You clear the squall and recover stray aether.");
            Add("enc.ion_squall.push_fail", "방전", "Discharge");
            Add("enc.ion_squall.push_fail.r", "방전이 선체를 태우고 코어를 흔들었습니다.", "A discharge scorches the hull and rattles the core.");
            Add("enc.static_fog.title", "정전기 안개", "THE STATIC FOG");
            Add("enc.static_fog.body", "정전기 안개가 시야를 지웁니다.", "Static fog erases all sight.");
            Add("enc.static_fog.chart", "[정찰선] 앞장서게 한다", "[Pathfinder] Send the pathfinder ahead");
            Add("enc.static_fog.chart.r", "정찰선이 안전한 길을 찾았습니다.", "The pathfinder finds a clear line.");
            Add("enc.static_fog.slow", "속도를 늦춘다 (에테르 1)", "Slow down (1 aether)");
            Add("enc.static_fog.slow.r", "천천히, 무사히 빠져나왔습니다.", "Slow and safe.");
            Add("enc.static_fog.fast", "전속으로 돌파한다", "Full speed");
            Add("enc.static_fog.fast.r", "안개를 단숨에 벗어났습니다.", "You burst out of the fog.");
            Add("enc.static_fog.fast_fail", "충돌", "Collision");
            Add("enc.static_fog.fast_fail.r", "잔해와 충돌해 장갑이 찢겼습니다.", "You clip wreckage and lose armor.");
            Add("enc.hail_front.title", "우박 전선", "THE HAIL FRONT");
            Add("enc.hail_front.body", "주먹만 한 우박이 선단을 두드립니다.", "Fist-sized hail hammers the convoy.");
            Add("enc.hail_front.brace", "[드워프] 장갑을 세워 버틴다", "[Dwarf] Brace the plating");
            Add("enc.hail_front.brace.r", "드워프들이 장갑을 지켰습니다.", "The dwarves hold the plating.");
            Add("enc.hail_front.climb", "에테르 2로 전선 위로 오른다", "Climb above it (2 aether)");
            Add("enc.hail_front.climb.r", "우박 위의 하늘은 고요했습니다.", "Above the front, the sky is still.");
            Add("enc.hail_front.endure", "버틴다", "Endure it");
            Add("enc.hail_front.endure.r", "우박이 장갑을 두들겼습니다.", "The hail dents the armor.");
            Add("enc.aether_bloom.title", "에테르 개화", "THE AETHER BLOOM");
            Add("enc.aether_bloom.body", "폭풍 속에 에테르 꽃이 피었습니다. 눈부시고 위험합니다.", "An aether bloom opens inside the storm — dazzling and dangerous.");
            Add("enc.aether_bloom.harvest", "가운데로 들어가 채집한다", "Fly into the bloom and harvest");
            Add("enc.aether_bloom.harvest.r", "에테르가 넘치지만 코어가 비명을 지릅니다.", "Aether floods in; the core howls.");
            Add("enc.aether_bloom.skirt", "가장자리만 스친다", "Skirt the edge");
            Add("enc.aether_bloom.skirt.r", "약간의 에테르를 얻었습니다.", "A little aether gained.");
            Add("enc.aether_bloom.avoid", "피한다", "Avoid it");
            Add("enc.aether_bloom.avoid.r", "개화가 뒤에서 사그라듭니다.", "The bloom fades behind you.");
            Add("enc.lightning_choir.title", "번개 성가", "THE LIGHTNING CHOIR");
            Add("enc.lightning_choir.body", "번개가 규칙적인 화음으로 칩니다. 공명자가 귀를 기울입니다.", "Lightning strikes in regular chords. Your resonator listens.");
            Add("enc.lightning_choir.conduct", "[엘프] 화음을 지휘해 코어를 채운다", "[Elf] Conduct the chords into the core");
            Add("enc.lightning_choir.conduct.r", "번개가 코어를 채웠습니다.", "Lightning fills the core.");
            Add("enc.lightning_choir.ground", "군수품 1을 피뢰침으로 쓴다", "Sacrifice 1 ordnance as a lightning rod");
            Add("enc.lightning_choir.ground.r", "번개가 미끼를 쳤습니다.", "The lightning takes the bait.");
            Add("enc.lightning_choir.endure", "버틴다", "Ride it out");
            Add("enc.lightning_choir.endure.r", "번개가 선단을 비껴갔습니다.", "The lightning passes you by.");
            Add("enc.lightning_choir.strike", "낙뢰", "Struck");
            Add("enc.lightning_choir.strike.r", "낙뢰가 선체를 강타했습니다.", "Lightning hammers the hull.");
            Add("enc.updraft_chasm.title", "상승기류 협곡", "THE UPDRAFT CHASM");
            Add("enc.updraft_chasm.body", "협곡에서 거대한 상승기류가 솟습니다.", "A vast updraft rises from the chasm.");
            Add("enc.updraft_chasm.high", "기류를 타고 고고도로 오른다", "Ride it to high altitude");
            Add("enc.updraft_chasm.high.r", "선단이 힘들이지 않고 고고도에 올랐습니다.", "The convoy climbs high without burning fuel.");
            Add("enc.updraft_chasm.avoid", "우회한다 (에테르 1)", "Go around (1 aether)");
            Add("enc.updraft_chasm.avoid.r", "협곡을 돌아갔습니다.", "You skirt the chasm.");
            Add("enc.cloud_reef.title", "구름 암초", "THE CLOUD REEF");
            Add("enc.cloud_reef.body", "굳은 구름 암초가 항로를 막습니다. 암초 속에 난파선이 박혀 있습니다.", "A reef of hardened cloud blocks the lane. Wrecks are lodged inside it.");
            Add("enc.cloud_reef.climb", "[고블린] 암초를 타고 잔해를 챙긴다", "[Goblin] Climb the reef for salvage");
            Add("enc.cloud_reef.climb.r", "고블린들이 잔해를 뜯어 왔습니다.", "The goblins strip the wrecks.");
            Add("enc.cloud_reef.around", "우회한다 (에테르 1)", "Go around (1 aether)");
            Add("enc.cloud_reef.around.r", "암초를 돌아갔습니다.", "You go around.");
            Add("enc.cloud_reef.risk", "틈으로 통과하며 인양한다", "Squeeze through and salvage");
            Add("enc.cloud_reef.risk.r", "틈을 통과하며 잔해를 챙겼습니다.", "You slip through and take salvage.");
            Add("enc.cloud_reef.scrape", "긁힘", "Scraped");
            Add("enc.cloud_reef.scrape.r", "암초가 선체를 긁었습니다.", "The reef tears at the hull.");
            Add("enc.whiteout.title", "화이트아웃", "THE WHITEOUT");
            Add("enc.whiteout.body", "눈보라가 모든 것을 지웁니다. 수송선이 대열을 잃기 시작합니다.", "A blizzard erases everything. Transports begin losing formation.");
            Add("enc.whiteout.anchor", "보급 1을 쓰며 정박해 기다린다", "Anchor and wait (1 supply)");
            Add("enc.whiteout.anchor.r", "눈보라가 지나갈 때까지 기다렸습니다.", "You wait out the storm.");
            Add("enc.whiteout.press", "밀고 나간다", "Press on");
            Add("enc.whiteout.press.r", "대열을 유지한 채 빠져나왔습니다.", "Formation holds.");
            Add("enc.whiteout.lost", "이탈", "Lost transports");
            Add("enc.whiteout.lost.r", "수송선 한 척이 대열에서 사라졌습니다.", "A transport is lost from the formation.");
            Add("enc.storm_leviathan.title", "폭풍 리바이어던", "THE STORM LEVIATHAN");
            Add("enc.storm_leviathan.body", "폭풍 속에서 거대한 그림자가 선단을 따라옵니다.", "Something vast follows the convoy inside the storm.");
            Add("enc.storm_leviathan.flee", "에테르 2로 전속 이탈", "Flee at full burn (2 aether)");
            Add("enc.storm_leviathan.flee.r", "그림자가 뒤처졌습니다.", "The shadow falls behind.");
            Add("enc.storm_leviathan.sing", "[조인] 노래로 달랜다", "[Avian] Sing to it");
            Add("enc.storm_leviathan.sing.r", "리바이어던이 노래를 따라 부르더니 멀어졌습니다.", "The leviathan answers the song and drifts away.");
            Add("enc.storm_leviathan.harpoon", "작살을 쏜다", "Harpoon it");
            Add("enc.storm_leviathan.harpoon.r", "리바이어던이 쓰러졌고 선단이 자원을 챙겼습니다.", "The leviathan falls and the convoy strips it.");
            Add("enc.storm_leviathan.harpoon_fail", "반격", "It turns on you");
            Add("enc.storm_leviathan.harpoon_fail.r", "리바이어던이 선체를 들이받았습니다.", "The leviathan rams the hull.");
            Add("enc.frozen_survey_team.title", "얼어붙은 측량단", "THE FROZEN SURVEY TEAM");
            Add("enc.frozen_survey_team.body", "빙운 고원의 관측소에서 측량단이 구조를 청합니다. 장비는 온전하지만 연료가 다 됐습니다.", "A survey team calls from an observatory on the icefield. Their instruments are intact; their fuel is gone.");
            Add("enc.frozen_survey_team.fetch", "에테르 1을 쓰며 데려온다", "Fly them out (1 aether)");
            Add("enc.frozen_survey_team.fetch.r", "측량단이 지도와 함께 합류했습니다.", "The surveyors join you, charts and all.");
            Add("enc.frozen_survey_team.dwarf", "[드워프] 발전기를 고쳐 관측소를 살린다", "[Dwarf] Repair their generator");
            Add("enc.frozen_survey_team.dwarf.r", "관측소가 되살아나 앞길의 결빙 정보를 넘겼습니다.", "The observatory lives again and radios icing warnings ahead.");
            Add("enc.frozen_survey_team.leave", "지나친다", "Pass by");
            Add("enc.frozen_survey_team.leave.r", "관측소의 불빛이 눈보라에 묻힙니다.", "The observatory's lights vanish into the snow.");
            Add("enc.abyss_diving_bell.title", "심연의 잠수종", "THE ABYSSAL BELL");
            Add("enc.abyss_diving_bell.body", "구름 밑바닥으로 내려간 잠수종 선단이 케이블에 매달려 있습니다. 끌어올리려면 힘이 듭니다.", "A diving-bell expedition hangs by its cable below the cloud floor. Hauling it up will strain the engines.");
            Add("enc.abyss_diving_bell.haul", "엔진을 혹사해 끌어올린다", "Haul them up");
            Add("enc.abyss_diving_bell.haul.r", "케이블이 버텼고 탐사대가 심연의 표본을 넘겼습니다.", "The cable holds; the explorers hand over samples from the deep.");
            Add("enc.abyss_diving_bell.cut", "케이블을 끊고 떠난다", "Cut the cable");
            Add("enc.abyss_diving_bell.cut.r", "선단은 아무 말 없이 항로를 계속했습니다.", "No one speaks as the convoy moves on.");
            Add("enc.abyss_diving_bell.orc", "[오크] 해병이 케이블을 손으로 당긴다", "[Orc] Marines haul by hand");
            Add("enc.abyss_diving_bell.orc.r", "오크들이 노래를 부르며 종을 끌어올렸습니다.", "The orcs sing as they drag the bell home.");
            Add("enc.cordon_escapees.title", "봉쇄선 탈출자", "CORDON ESCAPEES");
            Add("enc.cordon_escapees.body", "제국 봉쇄선을 뚫고 나온 소형선 여러 척이 추격을 받고 있습니다.", "A handful of small craft have broken through the Imperial cordon with pursuers close behind.");
            Add("enc.cordon_escapees.cover", "호위하며 받아들인다", "Cover them and take them in");
            Add("enc.cordon_escapees.cover.r", "탈출자들이 합류했지만 추격대가 위치를 알아챘습니다.", "The escapees join you; the pursuit now knows where you are.");
            Add("enc.cordon_escapees.decoy", "군수품 1로 기만 신호를 쏜다", "Fire a decoy beacon (1 ordnance)");
            Add("enc.cordon_escapees.decoy.r", "추격대가 미끼를 물었고 탈출자들이 조용히 합류했습니다.", "The pursuit takes the bait and the escapees slip aboard.");
            Add("enc.cordon_escapees.leave", "관여하지 않는다", "Stay clear");
            Add("enc.cordon_escapees.leave.r", "소형선들이 구름 속으로 흩어졌습니다.", "The craft scatter into the clouds.");
            Add("enc.drifting_nursery.title", "떠도는 보육선", "THE DRIFTING NURSERY");
            Add("enc.drifting_nursery.body", "보육선 한 척이 항법 장치 고장으로 표류합니다. 보호자는 둘뿐입니다.", "A nursery ship drifts with a dead navigation core. Two adults are all that watch over it.");
            Add("enc.drifting_nursery.adopt", "선단에 받아들인다", "Bring them into the convoy");
            Add("enc.drifting_nursery.adopt.r", "아이들이 선단 곳곳에 흩어져 새 가족을 만났습니다.", "The children find new families throughout the convoy.");
            Add("enc.drifting_nursery.navigator", "[조인] 항법 장치를 고쳐 스스로 가게 한다", "[Avian] Fix their navigation and send them on");
            Add("enc.drifting_nursery.navigator.r", "보육선이 안전한 항로로 떠났습니다.", "The nursery ship sails on along a safe course.");
            Add("enc.drifting_nursery.leave", "지나친다", "Pass by");
            Add("enc.drifting_nursery.leave.r", "선단이 침묵합니다.", "The convoy falls silent.");
            Add("enc.wrecked_gunship.title", "난파한 포함", "THE WRECKED GUNSHIP");
            Add("enc.wrecked_gunship.body", "제국 포함의 잔해에서 생존자들이 신호를 보냅니다. 무장은 대부분 온전합니다.", "Survivors signal from the wreck of an Imperial gunship. Most of its guns survived the crash.");
            Add("enc.wrecked_gunship.both", "생존자와 무장을 모두 회수한다 (보급 1)", "Recover crew and guns (1 supply)");
            Add("enc.wrecked_gunship.both.r", "포함 승무원이 합류했고 군수품이 늘었습니다.", "The gunship's crew join you and the magazines fill.");
            Add("enc.wrecked_gunship.guns", "무장만 뜯어간다", "Strip the guns only");
            Add("enc.wrecked_gunship.guns.r", "군수품은 얻었지만 생존자들의 눈길이 따라옵니다.", "You gain ordnance; the survivors' eyes follow you.");
            Add("enc.wrecked_gunship.leave", "떠난다", "Leave");
            Add("enc.wrecked_gunship.leave.r", "잔해가 구름 아래로 가라앉습니다.", "The wreck sinks beneath the clouds.");
            Add("enc.storm_shrine_hermits.title", "폭풍 사원의 은둔자", "THE STORM SHRINE HERMITS");
            Add("enc.storm_shrine_hermits.body", "폭풍 속 사원에 은둔자들이 남아 있습니다. 떠나기를 거부하지만 아이들은 보내려 합니다.", "Hermits keep a shrine inside the storm. They refuse to leave but will send their children with you.");
            Add("enc.storm_shrine_hermits.children", "아이들을 받아들인다", "Take the children");
            Add("enc.storm_shrine_hermits.children.r", "은둔자들이 축복과 함께 아이들을 보냈습니다.", "The hermits send their children with a blessing.");
            Add("enc.storm_shrine_hermits.persuade", "[엘프] 폭풍 노래로 설득한다", "[Elf] Persuade them with the storm-song");
            Add("enc.storm_shrine_hermits.persuade.r", "은둔자 전원이 선단에 합류했습니다.", "Every hermit comes aboard.");
            Add("enc.storm_shrine_hermits.leave", "존중하고 떠난다", "Respect their choice and leave");
            Add("enc.storm_shrine_hermits.leave.r", "사원의 종소리가 뒤에서 울립니다.", "The shrine's bell rings behind you.");
            Add("enc.quarantined_liner.title", "격리된 여객선", "THE QUARANTINED LINER");
            Add("enc.quarantined_liner.body", "제국이 격리 표식을 붙인 여객선이 표류합니다. 승객들은 건강해 보입니다.", "A liner drifts with Imperial quarantine markings. Its passengers look healthy enough.");
            Add("enc.quarantined_liner.inspect", "[병원선] 검진 후 받아들인다", "[Hospital ship] Screen and admit them");
            Add("enc.quarantined_liner.inspect.r", "격리 표식은 정치적 낙인이었습니다. 승객 전원이 합류했습니다.", "The quarantine was a political brand; every passenger joins.");
            Add("enc.quarantined_liner.risk", "검진 없이 받아들인다", "Admit them unscreened");
            Add("enc.quarantined_liner.risk.r", "아무 문제도 없었습니다.", "Nothing was wrong with them at all.");
            Add("enc.quarantined_liner.risk_fail", "전염", "Contagion");
            Add("enc.quarantined_liner.risk_fail.r", "선단에 열병이 돌아 25명을 잃었습니다.", "A fever runs through the convoy and 25 are lost.");
            Add("enc.quarantined_liner.leave", "떠난다", "Leave them");
            Add("enc.quarantined_liner.leave.r", "여객선의 등불이 멀어집니다.", "The liner's lamps recede.");
            Add("enc.lost_patrol.title", "길 잃은 순찰대", "THE LOST PATROL");
            Add("enc.lost_patrol.body", "탈영한 제국 순찰대가 길을 잃고 연료를 구걸합니다. 무장은 없습니다.", "A deserted Imperial patrol has lost its way and begs for fuel. They carry no weapons.");
            Add("enc.lost_patrol.fuel", "에테르 1을 준다", "Give them 1 aether");
            Add("enc.lost_patrol.fuel.r", "순찰대가 감사의 표시로 항로 정보를 넘겼습니다.", "The patrol repays you with route intelligence.");
            Add("enc.lost_patrol.recruit", "선단에 편입시킨다", "Recruit them");
            Add("enc.lost_patrol.recruit.r", "순찰대원들이 선단 경비를 맡았습니다.", "The patrol takes up convoy guard duty.");
            Add("enc.lost_patrol.leave", "돌려보낸다", "Send them off");
            Add("enc.lost_patrol.leave.r", "순찰대는 흩어졌습니다.", "The patrol scatters.");
            Add("enc.collapsing_spire.title", "무너지는 첨탑", "THE COLLAPSING SPIRE");
            Add("enc.collapsing_spire.body", "공중 첨탑 도시가 기울고 있습니다. 주민들이 위층에 갇혀 있습니다.", "A spire-city leans further every minute. Its people are trapped on the upper floors.");
            Add("enc.collapsing_spire.bridge", "선체를 붙여 다리를 만든다", "Bridge the gap with the hull");
            Add("enc.collapsing_spire.bridge.r", "주민들이 선체를 건너 살아났습니다.", "The people cross the hull to safety.");
            Add("enc.collapsing_spire.bridge_fail", "붕괴", "Collapse");
            Add("enc.collapsing_spire.bridge_fail.r", "첨탑이 무너지며 선체를 긁었고 일부만 구했습니다.", "The spire falls against the hull; only some are saved.");
            Add("enc.collapsing_spire.wings", "편대로 실어 나른다 (군수품 1)", "Ferry them by wing (1 ordnance)");
            Add("enc.collapsing_spire.wings.r", "편대가 왕복하며 주민을 옮겼습니다.", "The wings shuttle the people out.");
            Add("enc.collapsing_spire.leave", "떠난다", "Leave");
            Add("enc.collapsing_spire.leave.r", "첨탑이 구름 속으로 사라집니다.", "The spire disappears into the clouds.");
            Add("enc.throne_pilgrims_stranded.title", "왕좌의 순례자", "PILGRIMS OF THE THRONE");
            Add("enc.throne_pilgrims_stranded.body", "천공 왕좌를 향하던 순례선단이 연료를 다 쓰고 멈췄습니다. 그들은 문을 봤다고 말합니다.", "A pilgrim fleet bound for the Sky Throne has run dry. They say they have seen the gate.");
            Add("enc.throne_pilgrims_stranded.share", "에테르 2를 나눠 함께 간다", "Share 2 aether and travel together");
            Add("enc.throne_pilgrims_stranded.share.r", "순례자들이 문까지의 마지막 항로를 알려 줬습니다.", "The pilgrims describe the last stretch to the gate.");
            Add("enc.throne_pilgrims_stranded.take", "순례자만 태운다", "Take the pilgrims aboard");
            Add("enc.throne_pilgrims_stranded.take.r", "순례선은 버려졌지만 사람들은 살았습니다.", "The pilgrim ships are left behind; the people live.");
            Add("enc.throne_pilgrims_stranded.leave", "지나친다", "Pass by");
            Add("enc.throne_pilgrims_stranded.leave.r", "순례자들이 왕좌를 향해 기도합니다.", "The pilgrims pray toward the throne.");
            Add("enc.ice_locked_freighter.title", "결빙된 화물선", "THE ICE-LOCKED FREIGHTER");
            Add("enc.ice_locked_freighter.body", "화물선이 얼음에 갇혀 있습니다. 화물칸은 봉인된 채입니다.", "A freighter is locked in ice with its holds still sealed.");
            Add("enc.ice_locked_freighter.thaw", "천천히 녹여 화물을 꺼낸다", "Thaw it slowly");
            Add("enc.ice_locked_freighter.thaw.r", "보급과 자재를 회수했습니다.", "Supplies and materials recovered.");
            Add("enc.ice_locked_freighter.blast", "에테르로 얼음을 깬다 (에테르 1)", "Blast the ice (1 aether)");
            Add("enc.ice_locked_freighter.blast.r", "화물 전체를 빠르게 회수했습니다.", "The whole cargo comes free quickly.");
            Add("enc.ice_locked_freighter.leave", "떠난다", "Leave it");
            Add("enc.ice_locked_freighter.leave.r", "화물선은 얼음 속에 남았습니다.", "The freighter stays in the ice.");
            Add("enc.abyss_relic_field.title", "심연 유물 지대", "THE ABYSSAL RELIC FIELD");
            Add("enc.abyss_relic_field.body", "구름 밑바닥에서 고대 유물이 떠오릅니다. 코어가 불안하게 공명합니다.", "Ancient relics rise from the cloud floor. Your core resonates uneasily.");
            Add("enc.abyss_relic_field.gather", "최대한 수집한다", "Gather everything");
            Add("enc.abyss_relic_field.gather.r", "유물은 값지지만 코어가 진동합니다.", "The relics are priceless; the core shudders.");
            Add("enc.abyss_relic_field.careful", "[엘프] 공명을 조율하며 고른다", "[Elf] Tune the resonance while choosing");
            Add("enc.abyss_relic_field.careful.r", "코어가 안정된 채 유물을 골라냈습니다.", "The core stays calm as you pick the relics.");
            Add("enc.abyss_relic_field.skirt", "가장자리만 훑는다", "Skirt the field");
            Add("enc.abyss_relic_field.skirt.r", "약간의 유물을 얻었습니다.", "A few relics gathered.");
            Add("enc.cordon_supply_dump.title", "봉쇄선 보급소", "THE CORDON SUPPLY DUMP");
            Add("enc.cordon_supply_dump.body", "버려진 제국 보급소가 부표에 매달려 있습니다. 경비는 없지만 감시 장치가 있을지 모릅니다.", "An abandoned Imperial supply dump hangs from buoys. No guards, but perhaps sensors.");
            Add("enc.cordon_supply_dump.raid", "전부 털어 간다", "Raid it all");
            Add("enc.cordon_supply_dump.raid.r", "감시 장치는 없었습니다. 보급소를 비웠습니다.", "No sensors after all; the dump is yours.");
            Add("enc.cordon_supply_dump.raid_fail", "경보", "Alarm");
            Add("enc.cordon_supply_dump.raid_fail.r", "경보가 울리고 순찰함이 나타났습니다!", "An alarm sounds and a patrol arrives!");
            Add("enc.cordon_supply_dump.scout", "[정찰선] 감시 장치를 먼저 무력화한다", "[Pathfinder] Disable the sensors first");
            Add("enc.cordon_supply_dump.scout.r", "조용히 보급소를 비웠습니다.", "You empty the dump in silence.");
            Add("enc.cordon_supply_dump.leave", "건드리지 않는다", "Leave it");
            Add("enc.cordon_supply_dump.leave.r", "보급소가 뒤에서 흔들립니다.", "The dump sways behind you.");
            Add("enc.whale_bone_reef.title", "고래뼈 암초", "THE WHALEBONE REEF");
