            Add("enc.whale_bone_reef.mine", "결정을 캔다", "Mine the crystals");
            Add("enc.whale_bone_reef.mine.r", "에테르를 얻었습니다.", "Aether gained.");
            Add("enc.whale_bone_reef.respect", "[조인] 뼈를 건드리지 않고 노래로 결정을 부른다", "[Avian] Sing the crystals loose without touching the bones");
            Add("enc.whale_bone_reef.respect.r", "결정이 스스로 떨어졌습니다.", "The crystals drop on their own.");
            Add("enc.whale_bone_reef.leave", "지나간다", "Pass by");
            Add("enc.whale_bone_reef.leave.r", "암초가 뒤로 멀어집니다.", "The reef recedes.");
            Add("enc.sunken_arsenal.title", "가라앉은 무기고", "THE SUNKEN ARSENAL");
