            Add("enc.sunken_arsenal.dive_fail", "압력 손상", "Pressure damage");
            Add("enc.sunken_arsenal.dive_fail.r", "급강하로 선체가 뒤틀렸고 일부만 회수했습니다.", "The dive warps the hull; you recover a little.");
