            Add("enc.cordon_smuggler_tunnel.route.r", "다음 도약 비용이 줄었습니다.", "The next jumps cost less.");
            Add("enc.cordon_smuggler_tunnel.stores", "인양물 7로 보급 5·군수품 2", "5 supplies and 2 ordnance for 7 salvage");
            Add("enc.cordon_smuggler_tunnel.stores.r", "물자를 확보했습니다.", "Stores secured.");
            Add("enc.cordon_smuggler_tunnel.depart", "떠난다", "Leave");
            Add("enc.cordon_smuggler_tunnel.depart.r", "밀수꾼이 사라집니다.", "The smugglers vanish.");
