            Add("enc.wandering_alchemist.stabilise.r", "코어가 잠잠해졌습니다.", "The core settles.");
            Add("enc.wandering_alchemist.tonic", "보급 1로 사기 강장제", "Morale tonic for 1 supply");
            Add("enc.wandering_alchemist.tonic.r", "선단이 활기를 되찾았습니다.", "The convoy perks up.");
            Add("enc.wandering_alchemist.depart", "떠난다", "Leave");
            Add("enc.wandering_alchemist.depart.r", "연금술사가 손을 흔듭니다.", "The alchemist waves.");
