            Add("enc.refugee_market.swap.r", "보급이 늘었습니다.", "Supplies gained.");
            Add("enc.refugee_market.swap2", "보급 3을 에테르 2와 교환", "Trade 3 supplies for 2 aether");
            Add("enc.refugee_market.swap2.r", "연료가 늘었습니다.", "Fuel gained.");
            Add("enc.refugee_market.depart", "떠난다", "Leave");
            Add("enc.refugee_market.depart.r", "장터가 흩어집니다.", "The market disperses.");
            Add("enc.gunsmith_barge.title", "총포공 바지선", "THE GUNSMITH BARGE");
