            Add("enc.gunsmith_barge.tune.r", "무장실이 정비됐습니다.", "The weapons room is tuned.");
            Add("enc.gunsmith_barge.depart", "떠난다", "Leave");
            Add("enc.gunsmith_barge.depart.r", "바지선이 멀어집니다.", "The barge drifts off.");
            Add("enc.monastery_kitchens.title", "수도원 주방", "THE MONASTERY KITCHENS");
            Add("enc.monastery_kitchens.body", "수도원이 순례자에게 식량을 나눕니다. 기부를 받습니다.", "A monastery feeds pilgrims and accepts donations.");
            Add("enc.monastery_kitchens.donate", "인양물 4를 기부하고 식량을 받는다", "Donate 4 salvage for food");
            Add("enc.monastery_kitchens.donate.r", "보급과 축복을 받았습니다.", "Food and a blessing.");
            Add("enc.monastery_kitchens.free", "식량만 받는다", "Take the food only");
            Add("enc.monastery_kitchens.free.r", "수도사들이 조용히 식량을 건넸습니다.", "The monks hand over food in silence.");
            Add("enc.monastery_kitchens.depart", "떠난다", "Leave");
            Add("enc.monastery_kitchens.depart.r", "종소리가 울립니다.", "A bell rings.");
            Add("enc.captains_exchange.title", "함장 교환소", "THE CAPTAINS' EXCHANGE");
            Add("enc.captains_exchange.body", "자유 함장들이 정보와 장비를 교환하는 정박지입니다.", "An anchorage where free captains swap intelligence and gear.");
            Add("enc.captains_exchange.intel", "인양물 4로 항로 정보", "Route intelligence for 4 salvage");
            Add("enc.captains_exchange.intel.r", "앞길의 폭풍 정보를 얻었습니다.", "You learn where the storms are.");
            Add("enc.captains_exchange.human", "[인간] 옛 동료와 정보를 나눈다", "[Human] Trade stories with old comrades");
            Add("enc.captains_exchange.human.r", "공짜로 항로 정보와 군수품을 얻었습니다.", "Free intelligence and ordnance from old friends.");
            Add("enc.captains_exchange.depart", "떠난다", "Leave");
            Add("enc.captains_exchange.depart.r", "함장들이 경례합니다.", "The captains salute.");
            Add("enc.scrap_auction.title", "고철 경매", "THE SCRAP AUCTION");
            Add("enc.scrap_auction.body", "고철 경매가 열립니다. 헐값에 부품이 나오지만 품질은 복불복입니다.", "A scrap auction. Parts go cheap, quality is a gamble.");
            Add("enc.scrap_auction.bid", "인양물 5로 입찰", "Bid 5 salvage");
            Add("enc.scrap_auction.bid.r", "좋은 부품을 낙찰받았습니다.", "You win good parts.");
            Add("enc.scrap_auction.bid_fail", "불량품", "Junk");
            Add("enc.scrap_auction.bid_fail.r", "부품은 쓸모없었습니다.", "The parts are junk.");
            Add("enc.scrap_auction.sell", "인양물을 판다", "Sell scrap");
            Add("enc.scrap_auction.sell.r", "인양물 6을 보급 4로 바꿨습니다.", "6 salvage becomes 4 supplies.");
            Add("enc.scrap_auction.depart", "떠난다", "Leave");
            Add("enc.scrap_auction.depart.r", "경매가 끝났습니다.", "The auction closes.");
            Add("enc.ice_garrison.title", "빙운 수비대", "THE ICEFIELD GARRISON");
            Add("enc.ice_garrison.body", "얼어붙은 제국 수비대가 통행을 막습니다. 병사들은 추위에 지쳐 있습니다.", "A frozen Imperial garrison blocks the pass. Its soldiers are worn down by the cold.");
            Add("enc.ice_garrison.bribe", "보급 2를 넘긴다", "Hand over 2 supplies");
            Add("enc.ice_garrison.bribe.r", "수비대가 길을 열었습니다.", "The garrison opens the pass.");
            Add("enc.ice_garrison.dwarf", "[드워프] 난방을 고쳐 주고 통과한다", "[Dwarf] Fix their heating and pass");
            Add("enc.ice_garrison.dwarf.r", "수비대가 감사하며 길을 열었습니다.", "The grateful garrison waves you through.");
            Add("enc.ice_garrison.fight", "돌파한다", "Break through");
            Add("enc.ice_garrison.fight.r", "수비대가 포문을 엽니다.", "The garrison opens fire.");
            Add("enc.abyss_toll_keepers.title", "심연 통행세 징수인", "THE ABYSSAL TOLL KEEPERS");
            Add("enc.abyss_toll_keepers.body", "심연 해협의 징수인들은 제국 소속이 아닙니다. 그들은 인양물을 원합니다.", "The toll keepers of the Abyssal Strait answer to no empire. They want salvage.");
            Add("enc.abyss_toll_keepers.pay", "인양물 6을 낸다", "Pay 6 salvage");
            Add("enc.abyss_toll_keepers.pay.r", "징수인들이 길을 열었습니다.", "The keepers open the strait.");
            Add("enc.abyss_toll_keepers.goblin", "[고블린] 흥정으로 반값에 통과", "[Goblin] Haggle to half price");
            Add("enc.abyss_toll_keepers.goblin.r", "징수인들이 웃으며 받아들였습니다.", "The keepers accept with a grin.");
            Add("enc.abyss_toll_keepers.run", "돌파한다", "Run past");
            Add("enc.abyss_toll_keepers.run.r", "징수인들이 반응하지 못했습니다.", "The keepers fail to react.");
            Add("enc.abyss_toll_keepers.run_fail", "기뢰", "Mines");
            Add("enc.abyss_toll_keepers.run_fail.r", "기뢰가 터졌습니다.", "Mines detonate.");
            Add("enc.cordon_inquisitor.title", "봉쇄선 심문관", "THE CORDON INQUISITOR");
            Add("enc.cordon_inquisitor.body", "제국 심문관이 선단의 함장을 심문하겠다고 합니다.", "An Imperial inquisitor demands to question the convoy's captain.");
            Add("enc.cordon_inquisitor.submit", "심문에 응한다", "Submit to questioning");
            Add("enc.cordon_inquisitor.submit.r", "심문은 길었지만 통과했습니다.", "The questioning is long, but you pass.");
            Add("enc.cordon_inquisitor.human", "[인간] 옛 지위를 내세워 거절한다", "[Human] Invoke old rank and refuse");
            Add("enc.cordon_inquisitor.human.r", "심문관이 물러섰습니다.", "The inquisitor backs down.");
            Add("enc.cordon_inquisitor.fight", "포문을 연다", "Open fire");
            Add("enc.cordon_inquisitor.fight.r", "심문선이 결계를 올립니다.", "The inquisitor's ship raises its ward.");
            Add("enc.throne_gatekeepers.title", "왕좌의 문지기", "THE THRONE GATEKEEPERS");
            Add("enc.throne_gatekeepers.body", "천공 왕좌의 문지기들이 시험을 요구합니다. 통과하면 문까지의 길이 열립니다.", "The throne's gatekeepers demand a trial. Pass it and the way to the gate opens.");
            Add("enc.throne_gatekeepers.trial", "시험을 치른다", "Take the trial");
            Add("enc.throne_gatekeepers.trial.r", "문지기들이 길을 열고 선단을 축복했습니다.", "The gatekeepers open the way and bless the convoy.");
            Add("enc.throne_gatekeepers.trial_fail", "시험 실패", "Trial failed");
            Add("enc.throne_gatekeepers.trial_fail.r", "문지기들이 전투로 시험합니다!", "The gatekeepers test you in battle!");
            Add("enc.throne_gatekeepers.elf", "[엘프] 고대의 노래로 시험을 대신한다", "[Elf] Answer with the ancient song");
            Add("enc.throne_gatekeepers.elf.r", "문지기들이 무릎을 꿇었습니다.", "The gatekeepers kneel.");
            Add("enc.throne_gatekeepers.fight", "싸운다", "Fight");
            Add("enc.throne_gatekeepers.fight.r", "문지기들이 무장을 펼칩니다.", "The gatekeepers arm.");
            Add("enc.conscription_sweep.title", "징집 수색", "THE CONSCRIPTION SWEEP");
            Add("enc.conscription_sweep.body", "제국 징집대가 선단의 젊은이들을 요구합니다.", "An Imperial press gang demands the convoy's young.");
            Add("enc.conscription_sweep.refuse", "거부하고 싸운다", "Refuse and fight");
            Add("enc.conscription_sweep.refuse.r", "징집대가 포문을 엽니다.", "The press gang opens fire.");
            Add("enc.conscription_sweep.bribe", "인양물 8로 눈감게 한다", "Bribe them with 8 salvage");
            Add("enc.conscription_sweep.bribe.r", "징집대가 떠났습니다.", "The press gang leaves.");
            Add("enc.conscription_sweep.orc", "[오크] 해병을 세워 위협한다", "[Orc] Face them down with marines");
            Add("enc.conscription_sweep.orc.r", "징집대가 물러섰습니다.", "The press gang backs off.");
            Add("enc.tariff_station.title", "관세 기지", "THE TARIFF STATION");
            Add("enc.tariff_station.body", "관세 기지가 화물의 10분의 1을 요구합니다.", "A tariff station demands a tenth of your cargo.");
            Add("enc.tariff_station.pay", "보급 1·인양물 3을 낸다", "Pay 1 supply and 3 salvage");
            Add("enc.tariff_station.pay.r", "통과했습니다.", "You pass.");
            Add("enc.tariff_station.forge", "서류를 위조한다", "Forge the manifests");
            Add("enc.tariff_station.forge.r", "위조는 통했습니다.", "The forgery works.");
            Add("enc.tariff_station.forge_fail", "적발", "Caught");
            Add("enc.tariff_station.forge_fail.r", "위조가 적발돼 벌금을 물었습니다.", "The forgery is caught and fined.");
            Add("enc.tariff_station.fight", "돌파한다", "Break through");
            Add("enc.tariff_station.fight.r", "기지가 포문을 엽니다.", "The station opens fire.");
            Add("enc.deserter_hunt.title", "탈영병 수색", "THE DESERTER HUNT");
            Add("enc.deserter_hunt.body", "제국군이 탈영병을 찾아 선단을 수색하려 합니다. 선단에 탈영병이 있을지도 모릅니다.", "Imperial troops want to search the convoy for deserters. There may be some aboard.");
            Add("enc.deserter_hunt.allow", "수색을 허락한다", "Allow the search");
            Add("enc.deserter_hunt.allow.r", "몇 명이 끌려갔습니다.", "A few are taken away.");
            Add("enc.deserter_hunt.hide", "숨긴다", "Hide them");
            Add("enc.deserter_hunt.hide.r", "아무도 발견되지 않았습니다.", "No one is found.");
            Add("enc.deserter_hunt.hide_fail", "발각", "Discovered");
            Add("enc.deserter_hunt.hide_fail.r", "숨긴 이들이 발각돼 전투가 시작됩니다!", "The hidden are found; battle!");
            Add("enc.deserter_hunt.fight", "거부한다", "Refuse");
            Add("enc.deserter_hunt.fight.r", "제국군이 무장을 펼칩니다.", "The troops arm.");
            Add("enc.weather_station_seizure.title", "기상 관측소 압수", "THE WEATHER STATION SEIZURE");
            Add("enc.weather_station_seizure.body", "제국이 기상 관측소를 봉쇄했습니다. 관측 자료가 있으면 폭풍을 피할 수 있습니다.", "The Empire has sealed a weather station. Its data would let you dodge the storms.");
            Add("enc.weather_station_seizure.buy", "인양물 5로 자료를 산다", "Buy the data for 5 salvage");
            Add("enc.weather_station_seizure.buy.r", "폭풍 경로를 얻었습니다.", "You learn the storm tracks.");
            Add("enc.weather_station_seizure.avian", "[조인] 하늘을 읽어 자료 없이 통과한다", "[Avian] Read the sky instead");
            Add("enc.weather_station_seizure.avian.r", "조인이 폭풍을 읽어 냈습니다.", "The avian reads the storms.");
            Add("enc.weather_station_seizure.leave", "지나친다", "Pass by");
            Add("enc.weather_station_seizure.leave.r", "관측소가 멀어집니다.", "The station recedes.");
            Add("enc.refugee_registration.title", "피난민 등록소", "THE REFUGEE REGISTRY");
            Add("enc.refugee_registration.body", "제국 등록소가 선단 전원의 등록을 요구합니다. 등록하면 추적당합니다.", "An Imperial registry demands every soul aboard be recorded. Registered means tracked.");
            Add("enc.refugee_registration.register", "등록한다", "Register");
            Add("enc.refugee_registration.register.r", "추격군이 위치를 알았지만 통과했습니다.", "The pursuit learns your position; you pass.");
            Add("enc.refugee_registration.partial", "일부만 등록한다", "Register only some");
            Add("enc.refugee_registration.partial.r", "등록관이 눈치채지 못했습니다.", "The registrar notices nothing.");
            Add("enc.refugee_registration.partial_fail", "적발", "Caught");
            Add("enc.refugee_registration.partial_fail.r", "등록관이 알아채고 초계함을 불렀습니다.", "The registrar calls a picket.");
            Add("enc.refugee_registration.fight", "등록소를 파괴한다", "Destroy the registry");
            Add("enc.refugee_registration.fight.r", "등록소가 방어선을 부릅니다.", "The registry calls its guards.");
            Add("enc.admiral_parley.title", "제독의 회담", "THE ADMIRAL'S PARLEY");
            Add("enc.admiral_parley.body", "추격군 제독이 회담을 제안합니다. 항복하면 선단은 살려 준다고 합니다.", "The pursuing admiral proposes a parley: surrender, and the convoy lives.");
            Add("enc.admiral_parley.refuse", "거절하고 떠난다", "Refuse and leave");
            Add("enc.admiral_parley.refuse.r", "제독이 침묵했습니다. 선단은 결의를 다졌습니다.", "The admiral says nothing. The convoy hardens.");
            Add("enc.admiral_parley.stall", "시간을 끌며 정보를 캔다", "Stall and probe");
            Add("enc.admiral_parley.stall.r", "제독의 함대 배치를 알아냈습니다.", "You learn the fleet's disposition.");
            Add("enc.admiral_parley.fight", "기함을 노린다", "Strike the flagship");
            Add("enc.admiral_parley.fight.r", "제독의 기함이 응전합니다!", "The admiral's flagship answers!");
            Add("enc.ice_storm.title", "얼음 폭풍", "THE ICE STORM");
            Add("enc.ice_storm.body", "얼음 폭풍이 선단을 덮칩니다. 갑판이 얼어붙습니다.", "An ice storm engulfs the convoy. The decks freeze.");
            Add("enc.ice_storm.heat", "에테르 1로 갑판을 녹인다", "Heat the decks (1 aether)");
            Add("enc.ice_storm.heat.r", "편대가 출격 가능 상태로 유지됐습니다.", "The wings stay ready.");
            Add("enc.ice_storm.endure", "버틴다", "Endure");
            Add("enc.ice_storm.endure.r", "장갑에 얼음이 끼었습니다.", "Ice cakes the armor.");
            Add("enc.ice_storm.dwarf", "[드워프] 용광로 열을 돌린다", "[Dwarf] Route forge heat");
            Add("enc.ice_storm.dwarf.r", "드워프들이 선단을 녹였습니다.", "The dwarves thaw the convoy.");
            Add("enc.abyss_undertow.title", "심연 역류", "THE ABYSSAL UNDERTOW");
            Add("enc.abyss_undertow.body", "구름 밑바닥에서 역류가 선단을 끌어내립니다.", "An undertow from the cloud floor drags the convoy down.");
            Add("enc.abyss_undertow.climb", "에테르 2로 전속 상승", "Climb at full burn (2 aether)");
            Add("enc.abyss_undertow.climb.r", "선단이 빠져나왔습니다.", "The convoy pulls free.");
            Add("enc.abyss_undertow.ride", "역류를 타고 내려갔다 올라온다", "Ride it down and out");
            Add("enc.abyss_undertow.ride.r", "심연에서 에테르를 건졌습니다.", "You come up with aether from the deep.");
            Add("enc.abyss_undertow.ride_fail", "압력", "Pressure");
            Add("enc.abyss_undertow.ride_fail.r", "선체가 압력에 눌렸습니다.", "The hull buckles under pressure.");
            Add("enc.abyss_undertow.anchor", "보급 1을 쓰며 정박한다", "Anchor and wait (1 supply)");
            Add("enc.abyss_undertow.anchor.r", "역류가 지나갔습니다.", "The undertow passes.");
            Add("enc.cordon_searchlights.title", "봉쇄선 탐조등", "THE CORDON SEARCHLIGHTS");
            Add("enc.cordon_searchlights.body", "폭풍 속에서 제국 탐조등이 선단을 훑습니다.", "Imperial searchlights sweep the storm for you.");
            Add("enc.cordon_searchlights.dark", "전등화 관제로 숨는다", "Run dark");
            Add("enc.cordon_searchlights.dark.r", "탐조등이 지나갔습니다.", "The lights pass over.");
            Add("enc.cordon_searchlights.fast", "전속으로 벗어난다 (에테르 1)", "Burn out of the sweep (1 aether)");
            Add("enc.cordon_searchlights.fast.r", "벗어났습니다.", "You are clear.");
            Add("enc.cordon_searchlights.caught", "그대로 간다", "Press on");
            Add("enc.cordon_searchlights.caught.r", "들키지 않았습니다.", "Unseen.");
            Add("enc.cordon_searchlights.caught_fail", "포착", "Spotted");
            Add("enc.cordon_searchlights.caught_fail.r", "탐조등이 선단을 잡았습니다!", "The searchlights find you!");
            Add("enc.throne_aurora.title", "왕좌의 오로라", "THE THRONE AURORA");
            Add("enc.throne_aurora.body", "천공 왕좌 위로 오로라가 흐릅니다. 코어가 노래합니다.", "An aurora flows above the Sky Throne. The core sings.");
            Add("enc.throne_aurora.bathe", "오로라 속으로 들어간다", "Fly into the aurora");
            Add("enc.throne_aurora.bathe.r", "코어가 가득 찼습니다.", "The core brims.");
            Add("enc.throne_aurora.elf", "[엘프] 오로라를 조율한다", "[Elf] Tune the aurora");
            Add("enc.throne_aurora.elf.r", "코어가 안정된 채 채워졌습니다.", "The core fills and stays calm.");
            Add("enc.throne_aurora.skirt", "가장자리를 지난다", "Skirt it");
            Add("enc.throne_aurora.skirt.r", "약간의 에테르를 얻었습니다.", "A little aether.");
            Add("enc.ash_cloud.title", "재 구름", "THE ASH CLOUD");
            Add("enc.ash_cloud.body", "화산재 구름이 항로를 덮습니다. 엔진 필터가 막힙니다.", "A volcanic ash cloud covers the lane. Engine filters clog.");
            Add("enc.ash_cloud.slow", "천천히 통과한다 (에테르 1)", "Go slowly (1 aether)");
            Add("enc.ash_cloud.slow.r", "필터를 갈며 통과했습니다.", "You swap filters as you go.");
            Add("enc.ash_cloud.fast", "단숨에 돌파한다", "Punch through");
            Add("enc.ash_cloud.fast.r", "엔진이 손상됐습니다.", "The engines take damage.");
            Add("enc.ash_cloud.around", "우회한다 (에테르 2)", "Go around (2 aether)");
            Add("enc.ash_cloud.around.r", "깨끗한 하늘로 돌아갔습니다.", "Clear skies around.");
            Add("enc.ghost_lights.title", "도깨비불", "THE GHOST LIGHTS");
            Add("enc.ghost_lights.body", "폭풍 속에 도깨비불이 선단을 유혹합니다. 항로를 잃기 쉽습니다.", "Ghost lights in the storm lure the convoy off course.");
            Add("enc.ghost_lights.ignore", "무시하고 계기 비행", "Ignore them and fly by instruments");
            Add("enc.ghost_lights.ignore.r", "무사히 지났습니다.", "Safely through.");
            Add("enc.ghost_lights.follow", "따라간다", "Follow them");
            Add("enc.ghost_lights.follow.r", "도깨비불이 숨겨진 연료고로 이끌었습니다.", "The lights lead to a hidden fuel cache.");
            Add("enc.ghost_lights.follow_fail", "미로", "Lost");
            Add("enc.ghost_lights.follow_fail.r", "항로를 잃고 연료를 태웠습니다.", "You lose the lane and burn fuel.");
            Add("enc.ghost_lights.avian", "[조인] 진짜 별을 읽는다", "[Avian] Read the true stars");
            Add("enc.ghost_lights.avian.r", "조인이 선단을 이끌었습니다.", "The avian leads the convoy through.");
            Add("enc.crystal_rain.title", "결정 비", "THE CRYSTAL RAIN");
