            Add("enc.pressure_front.endure", "버틴다", "Endure");
            Add("enc.pressure_front.endure.r", "선단 일부가 앓았습니다.", "Some of the convoy fall ill.");
            Add("enc.pressure_front.climb", "에테르 1로 고도를 바꾼다", "Change altitude (1 aether)");
            Add("enc.pressure_front.climb.r", "전선을 피했습니다.", "You dodge the front.");
            Add("enc.thunder_leviathan_pod.title", "천둥 리바이어던 무리", "THE THUNDER LEVIATHAN POD");
